/**
 * Hand-written types mirroring the Pydantic response/request models in
 * `api/routes/*.py` (auth, mission, match, assignment). See client.ts for
 * why this is hand-written rather than generated from the OpenAPI schema.
 */

export type Role = "director" | "mission_lead" | "crew_member";

export type MissionStatus =
  | "draft"
  | "pending_approval"
  | "approved"
  | "active"
  | "completed"
  | "cancelled";

export type AssignmentStatus = "proposed" | "confirmed" | "declined";

export interface User {
  id: number;
  org_id: number;
  email: string;
  name: string;
  role: Role;
}

export interface LoginResponse {
  token: string;
  user: User;
}

export interface Mission {
  id: number;
  org_id: number;
  created_by: number;
  name: string;
  description: string;
  start_date: string;
  end_date: string;
  status: MissionStatus;
}

export interface Requirement {
  id: number;
  mission_id: number;
  skill_id: number;
  skill_name: string;
  min_proficiency: number;
  headcount: number;
  confirmed: number;
}

export interface MissionDetail extends Mission {
  requirements: Requirement[];
}

export interface MatchCandidate {
  crew_id: number;
  crew_name: string;
  score: number;
  proficiency_surplus_score: number;
  workload_score: number;
  availability_margin_score: number;
  breakdown: string;
}

export interface RequirementMatch {
  requirement_id: number;
  skill_id: number;
  min_proficiency: number;
  headcount: number;
  candidates: MatchCandidate[];
}

export interface Assignment {
  id: number;
  mission_id: number;
  requirement_id: number;
  crew_id: number;
  proposed_by: number;
  status: AssignmentStatus;
  proposed_at: string;
  responded_at: string | null;
}

/** Field-level shape the API's 422 handler emits (api/errors.py). */
export interface FieldError {
  field: string;
  message: string;
}

/** One entry in a Director/Lead's org roster (`GET /crew`, api/routes/crew.py). */
export interface CrewRosterEntry {
  user_id: number;
  name: string;
  email: string;
  skill_count: number;
}

/** A skill proficiency held by a crew member, as it appears on their profile. */
export interface CrewSkill {
  skill_id: number;
  skill_name: string;
  proficiency: number;
}

/** `GET /crew/{id}/profile` response — self, or (Director/Lead) another
 * crew member's, read-only in that case. */
export interface CrewProfile {
  user_id: number;
  org_id: number;
  name: string;
  email: string;
  contact: string | null;
  bio: string | null;
  skills: CrewSkill[];
}

/** An org-scoped skill taxonomy entry (`/skills`, FR-5). */
export interface Skill {
  id: number;
  org_id: number;
  name: string;
  category: string | null;
}

/** An unavailability window on a crew member's profile (FR-7). Absent any
 * window, a crew member defaults to available. */
export interface AvailabilityWindow {
  id: number;
  crew_id: number;
  start_date: string;
  end_date: string;
}

"""``/missions`` — mission CRUD, requirements, and the 6-state lifecycle
(FR-8/FR-9/FR-10/FR-11/FR-12/FR-17).

Every route is org-scoped through ``services.mission``'s
``models.mission.get_mission`` lookups (FR-1: cross-org id -> 404). Role
gating that doesn't depend on a loaded mission (create/add-requirement:
Mission Lead or Director; approve/reject: Director only) is a
``Depends(require_role(...))`` on the route, matching T2/T3's dependency-
injection pattern. Everything that *does* depend on the loaded mission —
the creator-only check behind ``submit``, the self-approval gate behind
``approve``/``reject`` — lives in ``services.mission.execute_mission_transition``,
the one Command executor for all six lifecycle actions; the six routes below
are thin translators into and out of it, not six separate implementations.
"""

from __future__ import annotations

from datetime import date

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field, model_validator
from sqlmodel import Session

from api.deps import get_current_user, require_role
from models.database import get_session
from models.enums import MissionStatus, Role
from models.mission import Mission
from models.user import User
from services.mission import (
    InvalidMissionTransitionError,
    MissingReasonError,
    MissionHasNoRequirementsError,
    MissionNotEditableError,
    MissionNotFoundError,
    NotMissionCreatorError,
    RequirementFulfillment,
    RequirementSkillNotFoundError,
    SelfApprovalError,
    add_requirement,
    create_mission,
    execute_mission_transition,
    get_mission_detail,
    list_org_missions,
)

router = APIRouter(prefix="/missions", tags=["missions"])


# --- schemas -----------------------------------------------------------


class MissionCreateRequest(BaseModel):
    name: str
    description: str
    start_date: date
    end_date: date

    @model_validator(mode="after")
    def _end_not_before_start(self) -> MissionCreateRequest:
        if self.end_date < self.start_date:
            raise ValueError("end_date must not be before start_date")
        return self


class RequirementCreateRequest(BaseModel):
    skill_id: int
    min_proficiency: int = Field(ge=1, le=5)
    headcount: int = Field(ge=1)


class RejectRequest(BaseModel):
    reason: str = Field(min_length=1)


class MissionOut(BaseModel):
    id: int
    org_id: int
    created_by: int
    name: str
    description: str
    start_date: date
    end_date: date
    status: MissionStatus


class RequirementOut(BaseModel):
    id: int
    mission_id: int
    skill_id: int
    skill_name: str
    min_proficiency: int
    headcount: int
    confirmed: int


class MissionDetailOut(MissionOut):
    requirements: list[RequirementOut]


# --- helpers -----------------------------------------------------------


def _to_mission_out(mission: Mission) -> MissionOut:
    return MissionOut.model_validate(mission, from_attributes=True)


def _to_requirement_out(fulfillment: RequirementFulfillment) -> RequirementOut:
    requirement = fulfillment.requirement
    return RequirementOut(
        id=requirement.id,  # type: ignore[arg-type]
        mission_id=requirement.mission_id,
        skill_id=requirement.skill_id,
        skill_name=fulfillment.skill_name,
        min_proficiency=requirement.min_proficiency,
        headcount=requirement.headcount,
        confirmed=fulfillment.confirmed,
    )


def _not_found() -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Mission not found")


def _forbidden(detail: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=detail)


def _apply_transition(
    session: Session,
    caller: User,
    mission_id: int,
    action: str,
    **payload: object,
) -> Mission:
    """Shared try/except around ``execute_mission_transition`` so the six
    action routes below stay a one-line call each."""
    try:
        return execute_mission_transition(
            session, caller.org_id, mission_id, caller, action, **payload
        )
    except MissionNotFoundError as exc:
        raise _not_found() from exc
    except InvalidMissionTransitionError as exc:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=str(exc)) from exc
    except MissionHasNoRequirementsError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Cannot submit a mission with no requirements",
        ) from exc
    except NotMissionCreatorError as exc:
        raise _forbidden("Only the mission's creator may submit it") from exc
    except SelfApprovalError as exc:
        raise _forbidden(
            "The mission's creator may not approve or reject their own mission"
        ) from exc
    except MissingReasonError as exc:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
            detail=[{"field": "reason", "message": "reason is required to reject a mission"}],
        ) from exc


# --- mission CRUD + requirements (FR-8) ---------------------------------


@router.post("", response_model=MissionOut, status_code=status.HTTP_201_CREATED)
def create_mission_route(
    payload: MissionCreateRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> MissionOut:
    mission = create_mission(
        session,
        caller.org_id,
        caller,
        name=payload.name,
        description=payload.description,
        start_date=payload.start_date,
        end_date=payload.end_date,
    )
    return _to_mission_out(mission)


@router.get("", response_model=list[MissionOut])
def list_missions_route(
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> list[MissionOut]:
    missions = list_org_missions(session, caller.org_id)
    return [_to_mission_out(mission) for mission in missions]


@router.get("/{mission_id}", response_model=MissionDetailOut)
def get_mission_route(
    mission_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> MissionDetailOut:
    try:
        detail = get_mission_detail(session, caller.org_id, mission_id)
    except MissionNotFoundError as exc:
        raise _not_found() from exc
    return MissionDetailOut(
        **_to_mission_out(detail.mission).model_dump(),
        requirements=[_to_requirement_out(fulfillment) for fulfillment in detail.requirements],
    )


@router.post(
    "/{mission_id}/requirements",
    response_model=RequirementOut,
    status_code=status.HTTP_201_CREATED,
)
def add_requirement_route(
    mission_id: int,
    payload: RequirementCreateRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> RequirementOut:
    try:
        fulfillment = add_requirement(
            session,
            caller.org_id,
            mission_id,
            skill_id=payload.skill_id,
            min_proficiency=payload.min_proficiency,
            headcount=payload.headcount,
        )
    except MissionNotFoundError as exc:
        raise _not_found() from exc
    except MissionNotEditableError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail="Requirements can only be added while the mission is in draft",
        ) from exc
    except RequirementSkillNotFoundError as exc:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Skill {payload.skill_id} not found in this org",
        ) from exc
    return _to_requirement_out(fulfillment)


# --- lifecycle actions (FR-9/FR-10/FR-11/FR-12) -------------------------
#
# Each route only differs in its `action` string, its role gate, and (for
# `reject`) its payload -- everything else routes into the one executor.


@router.post("/{mission_id}/submit", response_model=MissionOut)
def submit_mission_route(
    mission_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> MissionOut:
    mission = _apply_transition(session, caller, mission_id, "submit")
    return _to_mission_out(mission)


@router.post("/{mission_id}/approve", response_model=MissionOut)
def approve_mission_route(
    mission_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR)),
) -> MissionOut:
    mission = _apply_transition(session, caller, mission_id, "approve")
    return _to_mission_out(mission)


@router.post("/{mission_id}/reject", response_model=MissionOut)
def reject_mission_route(
    mission_id: int,
    payload: RejectRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR)),
) -> MissionOut:
    mission = _apply_transition(session, caller, mission_id, "reject", reason=payload.reason)
    return _to_mission_out(mission)


@router.post("/{mission_id}/activate", response_model=MissionOut)
def activate_mission_route(
    mission_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> MissionOut:
    mission = _apply_transition(session, caller, mission_id, "activate")
    return _to_mission_out(mission)


@router.post("/{mission_id}/complete", response_model=MissionOut)
def complete_mission_route(
    mission_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> MissionOut:
    mission = _apply_transition(session, caller, mission_id, "complete")
    return _to_mission_out(mission)


@router.post("/{mission_id}/cancel", response_model=MissionOut)
def cancel_mission_route(
    mission_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> MissionOut:
    mission = _apply_transition(session, caller, mission_id, "cancel")
    return _to_mission_out(mission)

"""``/crew/{user_id}/...`` — profile self-service, skill proficiency, and
availability windows (FR-4/FR-6/FR-7).

Every route below is org-scoped through ``services.crew.get_crew_member``
(FR-1: cross-org id -> 404). On top of that, each carries its own identity
rule beyond plain ``require_role`` RBAC:

* profile view  — self, or a Director/Lead viewing another crew member (FR-4)
* profile edit  — self only, and only a crew member (FR-4)
* skill set     — self, or a Director acting on the crew member's behalf (FR-6)
* availability  — self only, always (FR-7 names no "on behalf of" case)
"""

from __future__ import annotations

from datetime import date

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field, model_validator
from sqlmodel import Session

from api.deps import get_current_user, require_role
from models.availability_window import AvailabilityWindow
from models.database import get_session
from models.enums import Role
from models.user import User
from services.crew import (
    CrewMemberNotFoundError,
    CrewProfileView,
    CrewRosterEntry,
    OverlappingWindowError,
    SkillNotFoundError,
    WindowNotFoundError,
    add_availability_window,
    list_crew_availability_windows,
    list_org_crew_members,
    remove_availability_window,
    set_crew_skill_proficiency,
    update_crew_profile,
    view_crew_profile,
)

router = APIRouter(prefix="/crew", tags=["crew"])


# --- schemas ---------------------------------------------------------------


class CrewSkillOut(BaseModel):
    skill_id: int
    skill_name: str
    proficiency: int


class CrewProfileOut(BaseModel):
    user_id: int
    org_id: int
    name: str
    email: str
    contact: str | None
    bio: str | None
    skills: list[CrewSkillOut]


class CrewProfileUpdateRequest(BaseModel):
    name: str | None = None
    contact: str | None = None
    bio: str | None = None


class CrewSkillSetRequest(BaseModel):
    skill_name: str
    proficiency: int = Field(ge=1, le=5)


class AvailabilityWindowCreateRequest(BaseModel):
    start_date: date
    end_date: date

    @model_validator(mode="after")
    def _end_not_before_start(self) -> AvailabilityWindowCreateRequest:
        if self.end_date < self.start_date:
            raise ValueError("end_date must not be before start_date")
        return self


class AvailabilityWindowOut(BaseModel):
    id: int
    crew_id: int
    start_date: date
    end_date: date


class CrewRosterEntryOut(BaseModel):
    user_id: int
    name: str
    email: str
    skill_count: int


# --- helpers -----------------------------------------------------------


def _to_profile_out(view: CrewProfileView) -> CrewProfileOut:
    return CrewProfileOut(
        user_id=view.user.id,  # type: ignore[arg-type]
        org_id=view.user.org_id,
        name=view.user.name,
        email=view.user.email,
        contact=view.profile.contact,
        bio=view.profile.bio,
        skills=[
            CrewSkillOut(skill_id=skill.id, skill_name=skill.name, proficiency=cs.proficiency)  # type: ignore[arg-type]
            for cs, skill in view.skills
        ],
    )


def _to_window_out(window: AvailabilityWindow) -> AvailabilityWindowOut:
    return AvailabilityWindowOut.model_validate(window, from_attributes=True)


def _to_roster_entry_out(entry: CrewRosterEntry) -> CrewRosterEntryOut:
    return CrewRosterEntryOut(
        user_id=entry.user.id,  # type: ignore[arg-type]
        name=entry.user.name,
        email=entry.user.email,
        skill_count=entry.skill_count,
    )


def _not_found() -> HTTPException:
    return HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Crew member not found")


def _forbidden(detail: str) -> HTTPException:
    return HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=detail)


def _require_view_access(caller: User, target_user_id: int) -> None:
    if caller.id == target_user_id:
        return
    if caller.role in (Role.DIRECTOR, Role.MISSION_LEAD):
        return
    raise _forbidden("Requires role: director, mission_lead (or viewing your own profile)")


def _require_self_edit(caller: User, target_user_id: int) -> None:
    if caller.id != target_user_id or caller.role != Role.CREW_MEMBER:
        raise _forbidden("Requires role: crew_member, editing your own profile")


def _require_skill_set_access(caller: User, target_user_id: int) -> None:
    if caller.role == Role.DIRECTOR:
        return
    if caller.role == Role.CREW_MEMBER and caller.id == target_user_id:
        return
    raise _forbidden("Requires role: director, or crew_member setting your own proficiency")


def _require_self_crew(caller: User, target_user_id: int) -> None:
    if caller.id != target_user_id or caller.role != Role.CREW_MEMBER:
        raise _forbidden("Requires role: crew_member, managing your own availability")


# --- roster listing (Director/Lead only, PRD §7 "Listing") -------------


@router.get("", response_model=list[CrewRosterEntryOut])
def list_crew_route(
    session: Session = Depends(get_session),
    caller: User = Depends(require_role(Role.DIRECTOR, Role.MISSION_LEAD)),
) -> list[CrewRosterEntryOut]:
    entries = list_org_crew_members(session, caller.org_id)
    return [_to_roster_entry_out(entry) for entry in entries]


# --- profile -----------------------------------------------------------


@router.get("/{user_id}/profile", response_model=CrewProfileOut)
def get_crew_profile_route(
    user_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> CrewProfileOut:
    _require_view_access(caller, user_id)
    try:
        view = view_crew_profile(session, caller.org_id, user_id)
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    return _to_profile_out(view)


@router.patch("/{user_id}/profile", response_model=CrewProfileOut)
def update_crew_profile_route(
    user_id: int,
    payload: CrewProfileUpdateRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> CrewProfileOut:
    _require_self_edit(caller, user_id)
    try:
        view = update_crew_profile(
            session,
            caller.org_id,
            user_id,
            name=payload.name,
            contact=payload.contact,
            bio=payload.bio,
        )
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    return _to_profile_out(view)


# --- skill proficiency ---------------------------------------------------


@router.put("/{user_id}/skills", response_model=CrewSkillOut)
def set_crew_skill_route(
    user_id: int,
    payload: CrewSkillSetRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> CrewSkillOut:
    _require_skill_set_access(caller, user_id)
    try:
        crew_skill, skill = set_crew_skill_proficiency(
            session, caller.org_id, user_id, payload.skill_name, payload.proficiency
        )
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    except SkillNotFoundError as exc:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Skill '{payload.skill_name}' not found in this org",
        ) from exc
    return CrewSkillOut(
        skill_id=skill.id,  # type: ignore[arg-type]
        skill_name=skill.name,
        proficiency=crew_skill.proficiency,
    )


# --- availability --------------------------------------------------------


@router.post(
    "/{user_id}/availability",
    response_model=AvailabilityWindowOut,
    status_code=status.HTTP_201_CREATED,
)
def add_availability_window_route(
    user_id: int,
    payload: AvailabilityWindowCreateRequest,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> AvailabilityWindowOut:
    _require_self_crew(caller, user_id)
    try:
        window = add_availability_window(
            session, caller.org_id, user_id, payload.start_date, payload.end_date
        )
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    except OverlappingWindowError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail=(
                "Availability window overlaps an existing window "
                f"({exc.conflicting.start_date} to {exc.conflicting.end_date})"
            ),
        ) from exc
    return _to_window_out(window)


@router.get("/{user_id}/availability", response_model=list[AvailabilityWindowOut])
def list_availability_windows_route(
    user_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> list[AvailabilityWindowOut]:
    _require_self_crew(caller, user_id)
    try:
        windows = list_crew_availability_windows(session, caller.org_id, user_id)
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    return [_to_window_out(window) for window in windows]


@router.delete("/{user_id}/availability/{window_id}", status_code=status.HTTP_204_NO_CONTENT)
def remove_availability_window_route(
    user_id: int,
    window_id: int,
    session: Session = Depends(get_session),
    caller: User = Depends(get_current_user),
) -> None:
    _require_self_crew(caller, user_id)
    try:
        remove_availability_window(session, caller.org_id, user_id, window_id)
    except CrewMemberNotFoundError as exc:
        raise _not_found() from exc
    except WindowNotFoundError as exc:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Availability window not found"
        ) from exc

