1	import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from "react";
2	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
3	import { ApiError, api, configureAuthToken, configureUnauthorizedHandler } from "../api/client";
4	import type { User } from "../api/types";
5	
6	const TOKEN_STORAGE_KEY = "mission-control:token";
7	
8	interface AuthContextValue {
9	  user: User | null;
10	  /** "loading": token present, still confirming it with the API.
11	   * "unauthenticated": no token, or it turned out invalid/expired.
12	   * "authenticated": token confirmed, `user` is populated. */
13	  status: "loading" | "authenticated" | "unauthenticated";
14	  login: (email: string, password: string) => Promise<void>;
15	  isLoggingIn: boolean;
16	  loginError: string | null;
17	  logout: () => void;
18	}
19	
20	const AuthContext = createContext<AuthContextValue | null>(null);
21	
22	export function AuthProvider({ children }: { children: ReactNode }) {
23	  const queryClient = useQueryClient();
24	  const [token, setToken] = useState<string | null>(() => localStorage.getItem(TOKEN_STORAGE_KEY));
25	
26	  const logout = useCallback(() => {
27	    localStorage.removeItem(TOKEN_STORAGE_KEY);
28	    setToken(null);
29	    queryClient.clear();
30	  }, [queryClient]);
31	
32	  // Deliberately NOT a useEffect: a login (or logout) can swap the tree
33	  // from <LoginScreen> to the authenticated screens in the same commit,
34	  // whose queries fire from *their own* mount effects. React runs effects
35	  // bottom-up (children before parents), so if this ran in a useEffect
36	  // here, a freshly-mounted child's first fetch could beat this effect and
37	  // go out with a stale (or no) token. Setting it during render instead —
38	  // a plain synchronous assignment to a module-level function reference,
39	  // not a state update — guarantees it's current before any effect in this
40	  // commit runs.
41	  configureAuthToken(() => token);
42	  configureUnauthorizedHandler(logout);
43	
44	  const whoami = useQuery({
45	    queryKey: ["auth", "whoami"],
46	    queryFn: api.auth.whoami,
47	    enabled: token !== null,
48	    retry: false,
49	  });
50	
51	  // An expired/revoked token: whoami 401s (which also fires logout via
52	  // configureUnauthorizedHandler above, but that's async — this covers the
53	  // render before that runs).
54	  useEffect(() => {
55	    if (token !== null && whoami.isError) {
56	      logout();
57	    }
58	  }, [token, whoami.isError, logout]);
59	
60	  const loginMutation = useMutation({
61	    mutationFn: ({ email, password }: { email: string; password: string }) => api.auth.login(email, password),
62	    onSuccess: (data) => {
63	      localStorage.setItem(TOKEN_STORAGE_KEY, data.token);
64	      queryClient.setQueryData(["auth", "whoami"], data.user);
65	      setToken(data.token);
66	    },
67	  });
68	
69	  const login = useCallback(
70	    async (email: string, password: string) => {
71	      await loginMutation.mutateAsync({ email, password });
72	    },
73	    [loginMutation],
74	  );
75	
76	  const status: AuthContextValue["status"] =
77	    token === null ? "unauthenticated" : whoami.data ? "authenticated" : "loading";
78	
79	  const value = useMemo<AuthContextValue>(
80	    () => ({
81	      user: whoami.data ?? null,
82	      status,
83	      login,
84	      isLoggingIn: loginMutation.isPending,
85	      loginError: loginMutation.error instanceof ApiError ? loginMutation.error.message : null,
86	      logout,
87	    }),
88	    [whoami.data, status, login, loginMutation.isPending, loginMutation.error, logout],
89	  );
90	
91	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
92	}
93	
94	export function useAuth(): AuthContextValue {
95	  const ctx = useContext(AuthContext);
96	  if (!ctx) throw new Error("useAuth must be used within an AuthProvider");
97	  return ctx;
98	}
